def objective_signal(event):
    category = event.get("category", "unknown")
    prior = OBJECTIVE_PRIORS.get(category, 0.0)
    if not prior:
        return 0.0
    confidence = event.get("confidence", 0.0)
    strength = event.get("strength", 0.0)
    direction = event.get("direction", 0)
    if (not all(math.isfinite(float(value)) for value in (confidence, strength, direction))
            or confidence < GOAL_POSITIVE_EVENT_CONFIDENCE or strength <= 0.0
            or direction not in (-1, 1)):
        return 0.0
    score = prior * direction * min(1.0, strength) * min(1.0, confidence)
    if category in OBJECTIVE_RESOURCE_COST_CATEGORIES and score < 0.0:
        score *= OBJECTIVE_METRIC_CONSUMPTION_DISCOUNT
    return score

